const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={me:null,view:'home',settings:'mail',admin:'accounts',areas:null,parties:null,roles:null,credentials:null,jobs:null,files:[],selectedAreas:new Set(),excludeParties:new Set(),includeRoles:new Set(),includeEmails:new Map(),excludeEmails:new Map(),step:1};
const api=async(path,opts={})=>{const r=await fetch(path,{...opts,headers:{'Content-Type':'application/json',Accept:'application/json',...(opts.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok){const msg=d.error||`HTTP ${r.status}`;rememberNotice(msg,'error');throw new Error(msg)}return d};
function rememberNotice(text,type='error'){sessionStorage.setItem('ui:lastNotice',JSON.stringify({text,type,ts:Date.now()}));renderNotices()}
function clearNotice(){sessionStorage.removeItem('ui:lastNotice');renderNotices()}
function renderNotices(){const box=$('#global-notices');if(!box)return;box.innerHTML='';let item;try{item=JSON.parse(sessionStorage.getItem('ui:lastNotice')||'null')}catch{}if(!item)return;if(Date.now()-item.ts>86400000){clearNotice();return}const n=document.createElement('div');n.className=`notice ${item.type||'error'}`;n.innerHTML=`<span>${esc(item.text)}</span><button class="ghost" type="button">Stäng</button>`;$('button',n).onclick=clearNotice;box.append(n)}
function setTheme(v){document.documentElement.dataset.theme=v;localStorage.setItem('theme',v);$$('[data-theme-choice]').forEach(b=>b.classList.toggle('active',b.dataset.themeChoice===v))}
function modal(title,body){$('#modal-title').textContent=title;const c=$('#modal-body');c.innerHTML='';typeof body==='string'?c.innerHTML=body:c.append(body);$('#modal').classList.add('open')}
function closeModal(){$('#modal').classList.remove('open')}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot',"'":'&#39;'}[c]))}
function fmtDate(v){return v?new Date(Number(v)).toLocaleString('sv-SE'):''}
function n(v){return Number(v||0).toLocaleString('sv-SE')}
function currentRoute(){if(state.view==='settings')return `settings/${state.settings}`;if(state.view==='admin')return `admin/${state.admin}`;if(state.view==='send')return `send/${state.step}`;return state.view==='home'?'home':state.view}
function syncRoute(replace=false){const hash=`#${currentRoute()}`;if(location.hash===hash)return;(replace?history.replaceState:history.pushState).call(history,null,'',`${location.pathname}${location.search}${hash}`)}
function routeParts(){return location.hash.replace(/^#/,'').split('/').filter(Boolean)}
function applyRoute(){const parts=routeParts();let view=parts[0]||'home';if(location.pathname==='/admin'&&state.me?.isAdmin)view='admin';if(!['home','send','jobs','settings','admin'].includes(view))view='home';state.view=view;if(view==='settings'&&['mail','account','security','api'].includes(parts[1]))state.settings=parts[1];if(view==='admin'&&['accounts','sends','stats','feedback'].includes(parts[1]))state.admin=parts[1];if(view==='send'&&['1','2','3'].includes(parts[1]))state.step=Number(parts[1])}
function navTo(view){state.view=view;syncRoute();renderApp()}
function renderNav(){const views=[['home','Start'],['send','Nytt utskick'],['jobs','Utskick'],['settings','Inställningar']];if(state.me?.isAdmin)views.push(['admin','Admin']);for(const root of ['#desktop-nav','#drawer-nav']){const el=$(root);if(!el)continue;el.innerHTML='';for(const [id,label] of views){const b=document.createElement('button');b.className=(root==='#desktop-nav'?'nav-btn':'drawer-btn')+(state.view===id?' active':'');b.textContent=label;b.onclick=()=>{closeDrawer();if(id==='admin'&&location.pathname!=='/admin'){location.href=`/admin#admin/${state.admin}`;return}navTo(id)};el.append(b)}}}
function openDrawer(){$('#drawer').classList.add('open')}function closeDrawer(){$('#drawer').classList.remove('open')}
function page(title,lead){return `<h1 class="page-title">${esc(title)}</h1><p class="page-lead">${esc(lead)}</p>`}
function renderTurnstiles(){if(!window.turnstile)return;$$('.cf-turnstile').forEach(el=>{if(el.dataset.rendered)return;el.dataset.rendered='1';try{window.turnstile.render(el,{sitekey:el.dataset.sitekey,action:el.dataset.action})}catch{}})}
async function ensureAreas(){if(state.areas&&state.parties&&state.roles)return;[state.areas,state.parties,state.roles]=await Promise.all([api('/api/areas'),api('/api/parties'),api('/api/roles')])}
async function ensureCredentials(force=false){if(state.credentials&&!force)return;state.credentials=await api('/api/mail-credentials')}
async function ensureJobs(force=false){if(state.jobs&&!force)return;state.jobs=await api('/api/send-jobs')}
async function boot(){setTheme(localStorage.getItem('theme')||'dark');bindShell();renderNotices();const reset=new URLSearchParams(location.search).get('reset');if(reset){renderReset(reset);return}try{state.me=await api('/api/me');if(!state.me?.loggedIn)throw new Error('NO_SESSION');applyRoute();syncRoute(true);renderApp();window.addEventListener('hashchange',()=>{applyRoute();renderApp()})}catch{renderAuth()}}
function bindShell(){$('#menu-button').onclick=openDrawer;$('#drawer-backdrop').onclick=closeDrawer;$('#drawer-close').onclick=closeDrawer;$('#modal-backdrop').onclick=closeModal;$('#modal-close').onclick=closeModal;$('#logout-btn').onclick=async()=>{await api('/api/logout',{method:'POST'});location.href='/'};$$('[data-theme-choice]').forEach(b=>b.onclick=()=>setTheme(b.dataset.themeChoice))}
function renderAuth(){document.body.dataset.mode='auth';$('#app-header').hidden=true;$('#root').innerHTML=`<div class="auth-shell"><div class="auth-brand"><div class="brand" style="justify-content:center"><span class="brand-mark">🇸🇪</span><span>Politikerkontakt</span></div><p class="hint">Skriv till dina folkvalda från ditt eget mailkonto.</p></div><div class="auth-layout"><section class="panel"><h1 class="page-title" style="font-size:2rem">Logga in</h1><div class="oauth-grid"><a class="oauth-btn" href="/api/oauth/google/start">Google</a><a class="oauth-btn" href="/api/oauth/github/start">GitHub</a><a class="oauth-btn" href="/api/oauth/microsoft/start">Microsoft</a></div><div class="divider">eller</div><form id="login-form" class="stack"><label class="field"><span>E-post</span><input name="email" type="email" autocomplete="username" required></label><label class="field"><span>Lösenord</span><input name="password" type="password" autocomplete="current-password" required></label><label class="field" id="totp-row" hidden><span>2FA-kod</span><input name="totpCode" inputmode="numeric" autocomplete="one-time-code"></label><button class="primary">Logga in</button><button class="ghost" type="button" id="forgot-btn">Glömt lösenord?</button></form><div id="auth-msg"></div></section><aside class="panel"><h2>Nytt konto</h2><p class="hint">Skapa konto om du inte redan har ett.</p><form id="signup-form" class="stack"><label class="field"><span>E-post</span><input name="email" type="email" required></label><label class="field"><span>Lösenord</span><input name="password" type="password" minlength="10" required></label><div class="cf-turnstile" data-sitekey="0x4AAAAAADtfk0hF05HrDLLJ" data-action="turnstile-spin-v1"></div><button class="secondary">Skapa konto</button></form><div id="signup-msg"></div></aside></div></div>`;renderTurnstiles();$('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/api/login',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password'),totpCode:f.get('totpCode')||undefined})});location.reload()}catch(err){if(err.message==='TOTP_REQUIRED'){$('#totp-row').hidden=false;$('#auth-msg').innerHTML='<div class="notice warn">Ange koden från din autentiseringsapp.</div>'}else $('#auth-msg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`}};$('#forgot-btn').onclick=renderForgot;$('#signup-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const d=await api('/api/signup',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password'),turnstileToken:f.get('cf-turnstile-response')})});renderVerify(d.accountId)}catch(err){$('#signup-msg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`}}}
function renderForgot(){$('#root').innerHTML=`<div class="auth-shell"><section class="panel" style="max-width:560px;margin:auto"><button class="ghost" id="back-login">← Till inloggning</button><h1 class="page-title">Återställ lösenord</h1><form id="forgot-form" class="stack"><label class="field"><span>E-post</span><input type="email" name="email" required></label><div class="cf-turnstile" data-sitekey="0x4AAAAAADtfk0hF05HrDLLJ" data-action="turnstile-spin-v1"></div><button class="primary">Skicka återställningslänk</button></form><div id="forgot-msg"></div></section></div>`;renderTurnstiles();$('#back-login').onclick=renderAuth;$('#forgot-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await api('/api/request-password-reset',{method:'POST',body:JSON.stringify({email:f.get('email'),turnstileToken:f.get('cf-turnstile-response')})}).catch(()=>{});$('#forgot-msg').innerHTML='<div class="notice success">Om adressen finns skickas en återställningslänk.</div>'}}
function renderVerify(accountId){modal('Bekräfta e-post',`<p class="hint">Ange den sexsiffriga koden vi skickade.</p><form id="verify-form" class="stack"><input name="code" inputmode="numeric" required><button class="primary">Bekräfta</button></form><div id="verify-msg"></div>`);$('#verify-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/api/verify',{method:'POST',body:JSON.stringify({accountId,code:f.get('code')})});$('#verify-msg').innerHTML='<div class="notice success">Verifierat. Du kan nu logga in.</div>'}catch(err){$('#verify-msg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`}}}
function renderReset(token){document.body.dataset.mode='auth';$('#app-header').hidden=true;$('#root').innerHTML=`<div class="auth-shell"><section class="panel" style="max-width:560px;margin:auto"><h1 class="page-title">Sätt nytt lösenord</h1><p class="page-lead">Lyckad återställning stänger av 2FA automatiskt.</p><form id="reset-form" class="stack"><label class="field"><span>Nytt lösenord</span><input type="password" name="password" minlength="10" required></label><label class="field"><span>Bekräfta lösenord</span><input type="password" name="password2" minlength="10" required></label><button class="primary">Spara nytt lösenord</button></form><div id="reset-msg"></div></section></div>`;$('#reset-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('password')!==f.get('password2'))return $('#reset-msg').innerHTML='<div class="notice error">Lösenorden matchar inte.</div>';try{await api('/api/reset-password',{method:'POST',body:JSON.stringify({token,newPassword:f.get('password')})});history.replaceState(null,'','/');$('#reset-msg').innerHTML='<div class="notice success">Lösenordet är ändrat och 2FA är avstängt.</div>'}catch(err){$('#reset-msg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`}}}
function renderApp(){document.body.dataset.mode='app';$('#app-header').hidden=false;renderNav();const root=$('#root');root.innerHTML='';({home:renderHome,send:renderSend,jobs:renderJobs,settings:renderSettings,admin:renderAdmin}[state.view]||renderHome)(root)}
function renderHome(root){root.innerHTML=`<div class="page-shell"><section class="hero"><h1>Gör det enkelt att kontakta folkvalda.</h1><p>Välj mottagare, skriv brevet och skicka från ditt eget mailkonto. Du kan följa utskicket och justera takten efter att det startat.</p><div class="button-row"><button class="primary" id="new-send">Nytt utskick</button><button class="secondary" id="see-jobs">Visa utskick</button></div></section><div class="quick-grid"><div class="quick-card"><strong>1. Mottagare</strong><p>Välj bred kategori först.</p></div><div class="quick-card"><strong>2. Brev</strong><p>Skriv ditt brev.</p></div><div class="quick-card"><strong>3. Skicka</strong><p>Välj mailkonto och starta.</p></div></div></div>`;$('#new-send').onclick=()=>navTo('send');$('#see-jobs').onclick=()=>navTo('jobs')}
async function renderSend(root){root.innerHTML=`<div class="page-shell">${page('Nytt utskick','Tre korta steg. Avancerade val visas bara när du öppnar dem.')}<div class="stepper"><button class="step-btn ${state.step===1?'active':''}" data-step="1">1. Mottagare</button><button class="step-btn ${state.step===2?'active':''}" data-step="2">2. Brev</button><button class="step-btn ${state.step===3?'active':''}" data-step="3">3. Granska</button></div><section id="send-step" class="panel"><div class="empty">Laddar…</div></section></div>`;$$('[data-step]').forEach(b=>b.onclick=()=>{state.step=Number(b.dataset.step);syncRoute();renderSend(root)});try{if(state.step===1){await ensureAreas();renderRecipients()}else if(state.step===2)renderCompose();else{await ensureCredentials();renderReview()}}catch(e){$('#send-step').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
function areaGroups(){const m=new Map();for(const a of state.areas||[]){if(!m.has(a.area_type))m.set(a.area_type,[]);m.get(a.area_type).push(a)}return m}
function filterPayload(){return{areaNames:[...state.selectedAreas],excludeParties:[...state.excludeParties],excludeEmails:[...state.excludeEmails.keys()],includeRoles:[...state.includeRoles],includeEmails:[...state.includeEmails.keys()]}}
async function updateCount(){const d=await api('/api/recipients/count',{method:'POST',body:JSON.stringify(filterPayload())}).catch(()=>({count:'?'}));const el=$('#recipient-count');if(el)el.textContent=`${d.count} mottagare valda`}
function renderRecipients(){const el=$('#send-step'),groups=areaGroups(),labels={eu:'EU',regering:'Regering',riksdag:'Riksdag',media:'Media',region:'Regioner',kommun:'Kommuner',kyrka:'Kyrkan'},every=(state.areas||[]).length>0&&state.areas.every(a=>state.selectedAreas.has(a.area_name));el.innerHTML=`<div class="credential-head"><div><h2>Välj mottagare</h2><p class="hint">Börja brett. Finjustera under Avancerat.</p></div><button class="secondary" id="select-all-areas">${every?'Rensa alla':'Välj alla'}</button></div><div class="choice-grid" id="area-choices"></div><div id="recipient-count" class="notice">Beräknar…</div><details class="disclosure"><summary>Avancerat</summary><div class="stack"><label class="field"><span>Sök specifik politiker</span><input id="person-search" placeholder="Skriv minst två tecken"></label><div id="person-results"></div><label class="field"><span>Sök enskilt område</span><input id="area-search" placeholder="Kommun, region…"></label><div id="area-list" class="filter-list"></div><details class="disclosure"><summary>Befattning och parti</summary><div class="filter-columns"><section><strong class="filter-group-title">Befattning</strong><div id="role-list" class="filter-options"></div></section><section><strong class="filter-group-title">Uteslut parti</strong><div id="party-list" class="filter-options"></div></section></div></details><div><strong>Enskilt tillagda</strong><div id="include-chips"></div></div><div><strong>Exkluderade</strong><div id="exclude-chips"></div></div></div></details><div class="button-row"><button class="primary" id="to-compose">Nästa: Brev</button></div>`;$('#select-all-areas').onclick=()=>{if(every)state.selectedAreas.clear();else for(const a of state.areas)state.selectedAreas.add(a.area_name);renderRecipients()};const grid=$('#area-choices');for(const [type,arr] of groups){const all=arr.every(a=>state.selectedAreas.has(a.area_name));const b=document.createElement('button');b.className='choice'+(all?' selected':'');b.innerHTML=`<strong>${esc(labels[type]||type)}</strong><small>${arr.reduce((s,a)=>s+Number(a.count||0),0)} poster</small>`;b.onclick=()=>{for(const a of arr)all?state.selectedAreas.delete(a.area_name):state.selectedAreas.add(a.area_name);renderRecipients()};grid.append(b)}const renderRoleAndParty=()=>{const allowed=new Set(['ordförande','gruppledare','ledamot','ersättare']),roles=(state.roles||[]).filter(r=>allowed.has(String(r.role_key||'').toLowerCase())).sort((a,b)=>String(a.role).localeCompare(String(b.role),'sv-SE'));const roleList=$('#role-list');roleList.innerHTML='';for(const r of roles){const l=document.createElement('label');l.className='filter-option';l.innerHTML=`<input type="checkbox" ${state.includeRoles.has(r.role_key)?'checked':''}><span>${esc(r.role)} <span class="hint">(${r.count})</span></span>`;$('input',l).onchange=e=>{e.target.checked?state.includeRoles.add(r.role_key):state.includeRoles.delete(r.role_key);updateCount()};roleList.append(l)}if(!roles.length)roleList.innerHTML='<p class="hint">Inga relevanta befattningar i urvalet.</p>';const relevantParties=(state.parties||[]).filter(x=>!state.selectedAreas.size||state.selectedAreas.has(x.area_name)),parties=[...new Set(relevantParties.map(x=>x.party).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'sv-SE')),partyList=$('#party-list');partyList.innerHTML='';for(const p of parties){const l=document.createElement('label');l.className='filter-option';l.innerHTML=`<input type="checkbox" ${state.excludeParties.has(p)?'checked':''}><span>${esc(p)}</span>`;$('input',l).onchange=e=>{e.target.checked?state.excludeParties.add(p):state.excludeParties.delete(p);updateCount()};partyList.append(l)}if(!parties.length)partyList.innerHTML='<p class="hint">Inga partier finns för valda områden.</p>'};const renderAreaList=(q='')=>{const x=$('#area-list');x.innerHTML='';const rows=state.areas.filter(a=>!q||a.area_name.toLowerCase().includes(q.toLowerCase())).slice(0,200);for(const a of rows){const l=document.createElement('label');l.className='filter-row';l.innerHTML=`<input type="checkbox" ${state.selectedAreas.has(a.area_name)?'checked':''}><span class="filter-row-text">${esc(a.area_name)}</span><span class="filter-row-count">${a.count} poster</span>`;$('input',l).onchange=e=>{e.target.checked?state.selectedAreas.add(a.area_name):state.selectedAreas.delete(a.area_name);renderRoleAndParty();updateCount()};x.append(l)}if(!rows.length)x.innerHTML='<div class="empty">Inga områden matchar sökningen.</div>'};renderAreaList();renderRoleAndParty();$('#area-search').oninput=e=>renderAreaList(e.target.value);function chips(id,map){const c=$(id);c.innerHTML='';for(const [email,name] of map){const s=document.createElement('span');s.className='selected-chip';s.textContent=`${name} <${email}>`;const b=document.createElement('button');b.textContent='×';b.onclick=()=>{map.delete(email);chips(id,map);updateCount()};s.append(b);c.append(s)}}chips('#include-chips',state.includeEmails);chips('#exclude-chips',state.excludeEmails);let timer;$('#person-search').oninput=e=>{clearTimeout(timer);const q=e.target.value.trim();if(q.length<2)return $('#person-results').innerHTML='';timer=setTimeout(async()=>{const res=await api(`/api/politicians/search?q=${encodeURIComponent(q)}`),c=$('#person-results');c.innerHTML='';for(const p of res.slice(0,20)){const row=document.createElement('div');row.className='credential-card';row.innerHTML=`<div class="credential-head"><div><strong>${esc(p.name)}</strong><div class="hint">${esc(p.email)}</div></div><div class="button-row"><button class="secondary add">Lägg till</button><button class="ghost ex">Exkludera</button></div></div>`;$('.add',row).onclick=()=>{state.includeEmails.set(p.email,p.name);state.excludeEmails.delete(p.email);chips('#include-chips',state.includeEmails);chips('#exclude-chips',state.excludeEmails);updateCount()};$('.ex',row).onclick=()=>{state.excludeEmails.set(p.email,p.name);state.includeEmails.delete(p.email);chips('#include-chips',state.includeEmails);chips('#exclude-chips',state.excludeEmails);updateCount()};c.append(row)}},250)};updateCount();$('#to-compose').onclick=()=>{state.step=2;syncRoute();renderSend($('#root'))}}
let mammothPromise=null;function subjectFromFilename(name){return name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ').replace(/\s+/g,' ').trim()}function loadMammoth(){if(window.mammoth)return Promise.resolve(window.mammoth);if(mammothPromise)return mammothPromise;mammothPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/mammoth@1.10.0/mammoth.browser.min.js';s.onload=()=>window.mammoth?resolve(window.mammoth):reject(new Error('DOCX-stöd kunde inte laddas.'));s.onerror=()=>reject(new Error('DOCX-stöd kunde inte laddas.'));document.head.append(s)});return mammothPromise}
async function fileToHtml(file){const ext=file.name.toLowerCase().split('.').pop();if(ext==='docx'){const mammoth=await loadMammoth(),result=await mammoth.convertToHtml({arrayBuffer:await file.arrayBuffer()});return result.value||''}if(ext==='html'||ext==='htm')return file.text();if(ext==='txt'){const text=await file.text();return text.split(/\n{2,}/).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('\n')}throw new Error('Använd DOCX, HTML eller TXT för att fylla brevet automatiskt.')}
function renderCompose(){const el=$('#send-step');el.innerHTML=`<h2>Skriv brevet</h2><div class="stack"><label class="field"><span>Ämne</span><input id="letter-subject" value="${esc(sessionStorage.getItem('draft:subject')||'')}"></label><label class="field"><span>Brev <span id="format-badge" class="html-mode-badge" hidden>HTML</span></span><textarea id="letter-body" placeholder="Skriv brevet här…">${esc(sessionStorage.getItem('draft:body')||'')}</textarea></label><div id="letter-html-preview" class="letter-html-preview" hidden></div><details class="disclosure"><summary>Bilagor</summary><input type="file" id="letter-files" multiple accept=".pdf,.txt,.doc,.docx,.html,.htm"><p class="hint" id="file-hint">${state.files.length?`${state.files.length} fil(er) valda.`:'Max 10 MB per fil.'}</p><div class="button-row"><button type="button" class="secondary" id="use-file">Använd filen som brev</button><button type="button" class="secondary" id="preview-html" disabled>Förhandsvisa brevet</button></div><p class="hint">DOCX/HTML/TXT konverteras automatiskt till HTML. Du behöver inte välja HTML-läge.</p><div id="file-status" class="hint"></div></details></div><div class="button-row"><button class="secondary" id="back-rec">Tillbaka</button><button class="primary" id="to-review">Nästa: Granska</button></div>`;const subj=$('#letter-subject'),body=$('#letter-body');subj.oninput=e=>sessionStorage.setItem('draft:subject',e.target.value);body.oninput=e=>sessionStorage.setItem('draft:body',e.target.value);$('#letter-files').onchange=e=>{state.files=[...e.target.files];$('#file-hint').textContent=`${state.files.length} fil(er) valda.`};$('#use-file').onclick=async()=>{const file=$('#letter-files').files?.[0],status=$('#file-status');if(!file)return status.textContent='Välj en fil först.';try{status.textContent='Läser dokumentet…';const html=await fileToHtml(file);subj.value=subjectFromFilename(file.name);body.value=html;sessionStorage.setItem('draft:subject',subj.value);sessionStorage.setItem('draft:body',body.value);$('#format-badge').hidden=false;$('#preview-html').disabled=false;status.textContent='Ämnesrad och brevtext fylldes från dokumentet.'}catch(e){status.textContent=e.message}};$('#preview-html').onclick=()=>{const p=$('#letter-html-preview'),show=p.hidden;p.hidden=!show;body.hidden=show;if(show)p.innerHTML=body.value;$('#preview-html').textContent=show?'Visa HTML-kod':'Förhandsvisa brevet'};$('#back-rec').onclick=()=>{state.step=1;syncRoute();renderSend($('#root'))};$('#to-review').onclick=()=>{if(!body.value.trim())return rememberNotice('Skriv ett brev först.');state.step=3;syncRoute();renderSend($('#root'))}}
function fileToBase64(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=rej;r.readAsDataURL(file)})}
function renderReview(){const el=$('#send-step'),subj=sessionStorage.getItem('draft:subject')||'',body=sessionStorage.getItem('draft:body')||'';el.innerHTML=`<h2>Granska och skicka</h2><div class="review-kpis"><div class="kpi"><strong id="review-count">…</strong><span>Mottagare</span></div><div class="kpi"><strong>${state.credentials?.length||0}</strong><span>Mailkonton</span></div><div class="kpi"><strong>${state.files.length}</strong><span>Bilagor</span></div></div><div class="stack"><label class="field"><span>Skicka från</span><select id="send-credential"><option value="">Välj mailkonto…</option>${(state.credentials||[]).map(c=>`<option value="${esc(c.id)}">${esc(c.from_address)} · ${esc(c.provider)}</option>`).join('')}</select></label><div class="notice"><strong>${esc(subj||'(utan ämne)')}</strong><div class="hint">${esc(body.replace(/<[^>]+>/g,' ').slice(0,260))}</div></div><details class="disclosure"><summary>Avancerad utskickstakt</summary><div class="grid-3"><label class="field"><span>Högst per dag nu</span><input inputmode="numeric" type="number" id="limit-now" min="1"></label><label class="field"><span>Växla efter dagar</span><input inputmode="numeric" type="number" id="switch-days" min="1"></label><label class="field"><span>Högst per dag därefter</span><input inputmode="numeric" type="number" id="limit-after" min="1"></label></div></details></div><div class="button-row"><button class="secondary" id="back-compose">Tillbaka</button><button class="primary" id="send-now">Starta utskick</button></div><div id="send-status"></div>`;api('/api/recipients/count',{method:'POST',body:JSON.stringify(filterPayload())}).then(d=>{if($('#review-count'))$('#review-count').textContent=d.count});$('#back-compose').onclick=()=>{state.step=2;syncRoute();renderSend($('#root'))};$('#send-now').onclick=async()=>{const cred=$('#send-credential').value;if(!cred)return rememberNotice('Välj vilket mailkonto utskicket ska använda.');const b=$('#send-now');b.disabled=true;try{const attachments=[];for(const f of state.files)attachments.push({filename:f.name,contentType:f.type||'application/octet-stream',mode:'attach',base64Data:await fileToBase64(f)});const val=id=>$(id)?.value?.trim()?Number($(id).value):null;const d=await api('/api/send',{method:'POST',body:JSON.stringify({letterHtml:body,subject:subj||undefined,mailCredentialId:cred,...filterPayload(),attachments,dailyLimit:val('#limit-now'),switchAfterDays:val('#switch-days'),nextDailyLimit:val('#limit-after')})});sessionStorage.removeItem('draft:subject');sessionStorage.removeItem('draft:body');state.files=[];state.jobs=null;rememberNotice(`Utskicket startades för ${d.totalRecipients} mottagare.`,'success');state.step=1;navTo('jobs')}catch(e){$('#send-status').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}finally{b.disabled=false}}}
function statusLabel(s){return({pending:'Väntar',queued:'Köad',sending:'Skickar',done:'Klar',completed:'Klar',aborted:'Stoppad',stopped:'Stoppad',cancelled:'Avbruten',failed:'Misslyckad'})[s]||s}
function makeButton(txt,cls,fn){const b=document.createElement('button');b.className=cls;b.textContent=txt;b.onclick=fn;return b}
