async function drawJobs(){await Promise.all([ensureJobs(true),ensureCredentials()]);const c=$('#jobs-list');if(!c)return;c.innerHTML='';if(!state.jobs.length)return c.innerHTML='<div class="panel empty">Inga utskick ännu.</div>';for(const j of state.jobs){const sent=Number(j.sent_count||0),failed=Number(j.bounce_count||j.failed_count||0),remain=Math.max(0,Number(j.total_recipients||0)-sent-failed),pct=j.total_recipients?Math.round((sent+failed)/j.total_recipients*100):0,card=document.createElement('div');card.className='job-card';card.innerHTML=`<span class="badge ${esc(j.status)}">${statusLabel(j.status)}</span><div class="hint">Skapad ${fmtDate(j.created_at)}</div><div class="job-stats"><div class="job-stat"><strong>${sent}</strong><span>Skickade</span></div><div class="job-stat"><strong>${failed}</strong><span>Misslyckade</span></div><div class="job-stat"><strong>${remain}</strong><span>Kvar</span></div></div><div class="progress"><span style="width:${pct}%"></span></div>${j.last_error?`<div class="notice error"><strong>Senaste fel:</strong> ${esc(j.last_error)}</div>`:''}<div class="button-row"></div>`;const actions=$('.button-row',card);if(['pending','queued','sending'].includes(j.status)){actions.append(makeButton('Ändra takt','secondary',()=>openRate(j)),makeButton('Avbryt','danger',()=>jobAction(j,'cancel')))}else{if(['aborted','cancelled','stopped','failed'].includes(j.status)||failed>0)actions.append(makeButton('Försök igen','primary',()=>retryJob(j)));actions.append(makeButton('Ta bort','danger',()=>jobAction(j,'delete')))}c.append(card)}}
async function ask(opts){if(window.appConfirm)return window.appConfirm(opts);return confirm(opts.message||opts.title)}
async function jobAction(j,action){if(!await ask({title:action==='delete'?'Ta bort utskick?':'Avbryt utskick?',message:action==='delete'?'Utskicket tas bort från historiken.':'Utskicket stoppas.',confirmLabel:action==='delete'?'Ta bort':'Avbryt'}))return;await api(`/api/send-jobs/${j.id}/rate`,{method:'PATCH',body:JSON.stringify({action})});await drawJobs()}
