async function renderMailSettings(){await ensureCredentials(true);const p=$('#settings-panel');if(!p)return;p.innerHTML=`<div class="panel"><h2>Mailkonton</h2><p class="hint">Utskicket väljer alltid mailkonto explicit.</p><div id="cred-list"></div><button class="primary" id="add-cred">Koppla mailkonto</button></div>`;const l=$('#cred-list');for(const c of state.credentials){const d=document.createElement('div');d.className='credential-card';d.innerHTML=`<div class="credential-head"><div><strong>${esc(c.from_address)}</strong><div class="hint">${esc(c.provider)} · verifierad ${fmtDate(c.verified_at)}</div></div><button class="danger">Ta bort</button></div>`;$('button',d).onclick=async()=>{if(!await ask({title:'Ta bort mailkonto?',message:'Pågående utskick med kontot stoppas.',confirmLabel:'Ta bort'}))return;await api(`/api/mail-credentials/${c.id}`,{method:'DELETE'});state.credentials=null;renderMailSettings()};l.append(d)}if(!state.credentials.length)l.innerHTML='<div class="empty">Inget mailkonto kopplat.</div>';$('#add-cred').onclick=openAddCredential}
function openAddCredential(){modal('Koppla mailkonto',`<div class="stack"><label class="field"><span>Leverantör</span><select id="c-provider"><option value="icloud">iCloud</option><option value="gmail">Gmail</option><option value="outlook">Outlook</option><option value="yahoo">Yahoo</option><option value="generic">Annan SMTP</option></select></label><div id="generic-fields" class="grid-2" hidden><label class="field"><span>SMTP-server</span><input id="c-host"></label><label class="field"><span>Port</span><input inputmode="numeric" id="c-port" type="number" value="587"></label></div><label class="field"><span>E-postadress / avsändare</span><input id="c-from" type="email"></label><label class="field"><span>Användarnamn</span><input id="c-user"></label><label class="field"><span>Lösenord eller app-lösenord</span><input id="c-pass" type="password"></label><button class="primary" id="c-save">Testa och koppla</button><div id="c-msg"></div></div>`);$('#c-provider').onchange=e=>$('#generic-fields').hidden=e.target.value!=='generic';$('#c-save').onclick=async()=>{try{await api('/api/mail-credentials',{method:'POST',body:JSON.stringify({provider:$('#c-provider').value,host:$('#c-host').value||undefined,port:$('#c-port').value?Number($('#c-port').value):undefined,fromAddress:$('#c-from').value,user:$('#c-user').value,password:$('#c-pass').value})});state.credentials=null;closeModal();renderMailSettings()}catch(e){$('#c-msg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}}
