async function renderSecuritySettings(){const p=$('#settings-panel');p.innerHTML=`<div class="panel"><h2>Tvåfaktorsinloggning</h2><p class="hint">Status: <strong>${state.me.totpEnabled?'Aktiverad':'Avstängd'}</strong></p><button class="${state.me.totpEnabled?'danger':'primary'}" id="totp-action">${state.me.totpEnabled?'Inaktivera 2FA':'Aktivera 2FA'}</button></div><div class="panel"><h2>Länkade inloggningssätt</h2><div id="oauth-list">Laddar…</div></div>`;$('#totp-action').onclick=state.me.totpEnabled?async()=>{if(!await ask({title:'Inaktivera 2FA?',message:'Tvåfaktorsinloggning stängs av.',confirmLabel:'Inaktivera'}))return;await api('/api/totp/disable',{method:'POST'});state.me.totpEnabled=false;renderSecuritySettings()}:startTotp;try{const ids=await api('/api/oauth-identities'),l=$('#oauth-list');l.innerHTML='';for(const x of ids){const i=providerInfo(x.provider),d=document.createElement('div');d.className='credential-card provider-card';d.innerHTML=`<div class="provider-card-head"><span class="provider-mark ${esc(x.provider)}">${esc(i.mark)}</span><div class="provider-card-main"><strong class="provider-name">${esc(i.label)}</strong><div class="hint">${x.provider_email?esc(x.provider_email):'Mailadress sparas nästa gång du använder denna inloggning.'}</div>${x.created_at?`<div class="hint">Kopplad ${fmtDate(x.created_at)}</div>`:''}</div></div><button class="danger">Koppla bort</button>`;$('button',d).onclick=async()=>{if(!await ask({title:`Koppla bort ${i.label}?`,message:'Du kan länka inloggningssättet igen senare.',confirmLabel:'Koppla bort'}))return;await api(`/api/oauth-identities/${encodeURIComponent(x.provider)}`,{method:'DELETE'});renderSecuritySettings()};l.append(d)}if(!ids.length)l.innerHTML='<div class="empty">Inga externa inloggningar länkade.</div>'}catch(e){$('#oauth-list').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
