async function adminStats(){const s=await api('/api/admin/stats'),p=$('#admin-panel'),countries=(s.visitorCountries||[]).slice(0,12),leaders=(s.leaderboard||[]).slice(0,12);p.innerHTML=`<div class="grid-2"><a class="kpi stat-link" href="#admin/accounts"><strong>${n(s.totalAccounts)}</strong><span>Konton</span><small>Visa konton →</small></a><div class="kpi"><strong>${n(s.totalVisitors)}</strong><span>Besökare</span></div><div class="kpi"><strong>${n(s.totalLetters)}</strong><span>Brev</span></div><div class="kpi"><strong>${n(s.totalSent)}</strong><span>Skickade</span></div></div><div class="grid-2" style="margin-top:12px"><div class="panel"><h2>Besökare per land</h2><div class="stack">${countries.map(x=>`<div class="admin-row"><div class="credential-head"><strong>${esc(x.country==='??'?'Okänt':x.country)}</strong><span>${n(x.n)}</span></div></div>`).join('')}</div></div><div class="panel"><h2>Mest aktiva konton</h2><div class="stack">${leaders.map(x=>x.accountId?`<a class="admin-row" href="#admin/accounts/${encodeURIComponent(x.accountId)}" style="display:block;text-decoration:none"><div class="credential-head"><strong>${esc(x.email)}</strong><span>${n(x.sentCount)}</span></div><div class="hint">Visa konto →</div></a>`:`<div class="admin-row"><div class="credential-head"><strong>${esc(x.email)}</strong><span>${n(x.sentCount)}</span></div></div>`).join('')}</div></div></div>`}
async function removeFeedback(id){await api(`/api/admin/feedback/${encodeURIComponent(id)}`,{method:'DELETE'})}
async function clearFeedback(){await api('/api/admin/feedback',{method:'DELETE'})}
function feedbackModal(f,account){const canReply=Boolean(f.wants_reply&&f.reply_to),mailto=canReply?`mailto:${encodeURIComponent(f.reply_to)}?subject=${encodeURIComponent('Angående din kontakt med Politikerkontakt')}`:'';modal('Feedbackärende',`<div class="stack"><div class="panel"><strong>${f.kind==='contact'?'Kontaktfråga':'Feedback'}</strong><div class="hint">${fmtDate(f.created_at)}</div><p style="white-space:pre-wrap">${esc(f.message)}</p></div><div class="panel"><div><span class="hint">Återkoppling</span><br><strong>${canReply?'Önskas':'Inte begärd'}</strong></div>${f.reply_to?`<div><span class="hint">E-post</span><br><a href="${mailto}">${esc(f.reply_to)}</a></div>`:''}${f.account_id?`<div><span class="hint">Konto</span><br><a href="#admin/accounts/${encodeURIComponent(f.account_id)}"><code>${esc(f.account_id)}</code></a>${account?.email?` · ${esc(account.email)}`:''}</div>`:''}</div>${canReply?`<a class="primary" href="${mailto}">Svara via e-post</a>`:''}<button class="danger" id="feedback-delete">Ta bort feedback</button></div>`);$('#feedback-delete').onclick=async()=>{if(!await ask({title:'Ta bort feedback?',message:'Ärendet tas bort permanent.',confirmLabel:'Ta bort'}))return;await removeFeedback(f.id);closeModal();adminFeedback()}}
async function adminFeedback(){const p=$('#admin-panel'),[rows,accounts]=await Promise.all([api('/api/admin/feedback'),api('/api/admin/accounts')]),accountById=new Map(accounts.map(a=>[String(a.id),a]));p.innerHTML=`<div class="panel"><div class="feedback-controls button-row"><button class="secondary" id="feedback-range">Rensa efter datum…</button><button class="danger" id="feedback-clear">Rensa all feedback</button></div><div id="admin-feedback"></div></div>`;const l=$('#admin-feedback');for(const f of rows){const a=accountById.get(String(f.account_id||'')),b=document.createElement('button');b.type='button';b.className='admin-row feedback-ticket';b.innerHTML=`<div class="credential-head"><div><strong>${esc((f.message||'').slice(0,90))}${(f.message||'').length>90?'…':''}</strong><div class="hint">${fmtDate(f.created_at)}${a?.email?' · '+esc(a.email):f.reply_to?' · '+esc(f.reply_to):''}</div></div><span>›</span></div>${f.wants_reply?'<div class="feedback-badge">Svar önskas</div>':''}`;b.onclick=()=>feedbackModal(f,a);l.append(b)}if(!rows.length)l.innerHTML='<div class="empty">Ingen feedback.</div>';$('#feedback-clear').onclick=async()=>{if(!await ask({title:'Rensa all feedback?',message:'Alla feedbackärenden tas bort permanent.',confirmLabel:'Rensa allt'}))return;await clearFeedback();adminFeedback()};$('#feedback-range').onclick=()=>{const today=new Date().toISOString().slice(0,10),yesterday=new Date(Date.now()-86400000).toISOString().slice(0,10);modal('Rensa feedback efter datum',`<div class="grid-2"><label class="field"><span>Från datum</span><input id="purge-from" type="date" value="${yesterday}"></label><label class="field"><span>Till datum</span><input id="purge-to" type="date" value="${today}"></label></div><button class="danger" id="purge-run">Rensa intervallet</button><div id="purge-status" class="hint"></div>`);$('#purge-run').onclick=async()=>{const from=new Date($('#purge-from').value);from.setHours(0,0,0,0);const to=new Date($('#purge-to').value);to.setHours(23,59,59,999);const matches=rows.filter(f=>Number(f.created_at)>=from.getTime()&&Number(f.created_at)<=to.getTime());if(!matches.length)return $('#purge-status').textContent='Ingen feedback matchade intervallet.';if(!await ask({title:`Ta bort ${matches.length} ärenden?`,message:'Matchande feedback tas bort permanent.',confirmLabel:'Ta bort'}))return;for(const f of matches)await removeFeedback(f.id);closeModal();adminFeedback()}}}
boot();
